import{_ as a,o,c,ag as t}from"./chunks/framework.DyxC4IQh.js";const u=JSON.parse('{"title":"应用设置","description":"主界面上每一项设置：通知键、点击键、WASD 与 HJKL 开关、排除应用。","frontmatter":{"description":"主界面上每一项设置：通知键、点击键、WASD 与 HJKL 开关、排除应用。"},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1792210681000}'),d={name:"guide/settings.md"};function i(r,e,n,s,p,h){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="应用设置" tabindex="-1">应用设置 <a class="header-anchor" href="#应用设置" aria-label="Permalink to &quot;应用设置&quot;">​</a></h1><p>启动 VimAct 主界面就是全部设置。v0.1 只暴露真正需要改的几项，其余用默认值。界面上的文字目前是英文。</p><p>顶部那行状态（<code>Status: enabled</code> / <code>Status: disabled</code>）报告无障碍服务的开关状态，下面的按钮直接把系统无障碍设置页打开。</p><h2 id="通知键-notification-key" tabindex="-1">通知键（Notification key） <a class="header-anchor" href="#通知键-notification-key" aria-label="Permalink to &quot;通知键（Notification key）&quot;">​</a></h2><p><code>Space</code> 和 <code>Enter</code> 二选一，决定角标上印 <code>␣</code> 还是 <code>⏎</code>，见<a href="/vimact-site/guide/notification.html">通知栏一键</a>。</p><h2 id="光标点击键-cursor-click-key" tabindex="-1">光标点击键（Cursor click key） <a class="header-anchor" href="#光标点击键-cursor-click-key" aria-label="Permalink to &quot;光标点击键（Cursor click key）&quot;">​</a></h2><p>同样是 <code>Space</code> / <code>Enter</code> 二选一。这个键只在 hint 模式之外生效；进入 hint 模式后点击光标固定用 <code>Space</code>。</p><p>两项默认都是 <code>Space</code>，撞在同一个键上时看屏幕上有没有光标：光标在，这一下给光标；光标不在，才去点通知横幅。想让两者各走各路，把其中一项切成 <code>Enter</code>。</p><h2 id="方向键-arrow-keys-navigate" tabindex="-1">方向键（Arrow keys (navigate)） <a class="header-anchor" href="#方向键-arrow-keys-navigate" aria-label="Permalink to &quot;方向键（Arrow keys (navigate)）&quot;">​</a></h2><p>两个开关，分别控制 WASD 与 HJKL 是否驱动<a href="/vimact-site/guide/cursor.html">空间光标</a>。默认都开着。</p><p>这个开关同时改变标签字符集：关掉的哪组，那几个字母就还给标签。只关 WASD，<code>w</code> <code>a</code> <code>s</code> <code>d</code> 可以出现在标签里，<code>h</code> <code>j</code> <code>k</code> <code>l</code> 仍然被保留。全关之后标签字符集扩到 24 个（只剩 <code>f</code> 和 <code>q</code> 被占用），标签平均更短，也更容易在一屏里出现单字符标签。</p><h2 id="排除应用-excluded-apps-vimact-off" tabindex="-1">排除应用（Excluded apps (VimAct off)） <a class="header-anchor" href="#排除应用-excluded-apps-vimact-off" aria-label="Permalink to &quot;排除应用（Excluded apps (VimAct off)）&quot;">​</a></h2><p>列出这台机器上能启动的应用，按应用名排序（比较时忽略大小写），VimAct 自己不在列表里，每个名字右边一个开关。开关打开意味着 VimAct 在那个应用里不出手：不消费按键、不贴标签、不动光标。</p><p>游戏和自绘应用里标签本来就画不出来，留着介入只会添乱。某些终端和编辑器自带键盘操作，要的是完整的按键序列，VimAct 半路截走几个键就把序列打断了。</p><p>判定看的是当前活动窗口的包名。命中排除列表时服务直接放行按键，等同于没装。</p><p>这条判定走在 hint 模式之外的按键路径上，于是留了一个口子：在别的应用里按 <code>F</code> 进了 hint 模式，再切到被排除的应用，模式不会自己退出，标签跟着新界面重扫出来，按键也继续被吃掉。按 <code>F</code> 或 <code>Esc</code> 退出来，排除才真正生效。</p><p>另一处例外要说清楚：通知角标钉的是 SystemUI 的横幅窗口，与前台应用无关，所以在排除应用里它照样会出现。此时通知键也属于放行的按键，VimAct 不接手，于是会出现「看得见角标、按下去没反应」的情形。想让横幅上不留东西，把无障碍开关关掉即可，只排除应用是不够的。</p><h2 id="触发键" tabindex="-1">触发键 <a class="header-anchor" href="#触发键" aria-label="Permalink to &quot;触发键&quot;">​</a></h2><p>默认 <code>F</code>，同时也是 hint 模式内的退出键。配置项存在，但 v0.1 没有做修改入口，界面上改不了。</p><p><code>F</code> 被排除在标签字符集之外，<code>Q</code> 也是（它同样能退出 hint 模式）。</p><h2 id="配置存在哪里" tabindex="-1">配置存在哪里 <a class="header-anchor" href="#配置存在哪里" aria-label="Permalink to &quot;配置存在哪里&quot;">​</a></h2><p>应用的 <code>SharedPreferences</code>，本地文件，不同步、不上传。卸载应用配置一起消失。</p><h2 id="没有的东西" tabindex="-1">没有的东西 <a class="header-anchor" href="#没有的东西" aria-label="Permalink to &quot;没有的东西&quot;">​</a></h2><p>配色、字号、标签位置、自定义字符集、三个字母以上的标签、按应用定制规则、长按 hint、文本过滤，这些在 v0.1 都没实现，界面上也就没有对应入口。计划里的项见首页说明，不要把预期放在这里。</p>',24)])])}const f=a(d,[["render",i]]);export{u as __pageData,f as default};
